ReplacementContent:
"/* 宽高比自适应容器，确保 clean 背景底图与 4角时钟、天秤 cutouts 保持等比例视口裁剪，实现像素级重合 */
.bg-aspect-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  height: 100%; /* 默认降级方案：撑满父级，防止因浏览器不支持媒体查询导致尺寸坍塌为 0 */
  will-change: transform;
}

/* 移动端 (941/1672 = 0.5628) cover 填充算法 (使用 1.1 倍视口尺寸，以覆盖父级 .parallax-bg-layer 的 110% 视差安全边距) */
@media screen and (max-width: 819px) and (min-aspect-ratio: 941/1672) {
  .bg-aspect-container {
    width: 110vw;
    height: 195.45vw; /* 110vw * (1672/941) */
  }
}
@media screen and (max-width: 819px) and (max-aspect-ratio: 941/1672) {
  .bg-aspect-container {
    height: 110vh;
    width: 61.91vh; /* 110vh * (941/1672) */
  }
}

/* 宽屏桌面端 (1672/941 = 1.7768) cover 填充算法 (使用 1.1 倍视口尺寸，以覆盖父级 .parallax-bg-layer 的 110% 视差安全边距) */
@media screen and (min-width: 820px) and (min-aspect-ratio: 1672/941) {
  .bg-aspect-container {
    width: 110vw;
    height: 61.91vw; /* 110vw * (941/1672) */
  }
}
@media screen and (min-width: 820px) and (max-aspect-ratio: 1672/941) {
  .bg-aspect-container {
    height: 110vh;
    width: 195.45vh; /* 110vh * (1672/941) */
  }
}"

